<?php
namespace App\Modules\Identity\Controllers;
use App\Http\Controllers\Controller;
use App\Models\User;
use App\Modules\Identity\Services\IdentitySecurity as Security;
use App\Modules\Identity\Services\Outbox;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\Rules\Password;
class InternalTeamController extends Controller {
 private function admin(Request $r):void{abort_unless($r->user()->is_platform_admin,403);}
 public function index(Request $r){$this->admin($r);return response()->json(['users'=>DB::table('users')->where(fn($q)=>$q->where('is_support_staff',true)->orWhere('is_support_coordinator',true))->get(['id','name','email','is_support_staff','is_support_coordinator','internal_active','internal_version']),'invitations'=>DB::table('organization_invitations')->latest('id')->get(['id','email','staff','coordinator','expires_at','accepted_at'])]);}
 public function invite(Request $r){$this->admin($r);$d=$r->validate(['email'=>['required','email','max:254'],'staff'=>['required','boolean'],'coordinator'=>['required','boolean']]);abort_unless($d['staff']||$d['coordinator'],422,'Choisissez un rôle interne.');$email=strtolower(trim($d['email']));$token=Str::random(64);DB::transaction(function()use($r,$d,$email,$token){DB::table('users')->where('id',$r->user()->id)->lockForUpdate()->firstOrFail();$old=DB::table('organization_invitations')->where('email',$email)->lockForUpdate()->first();$u=DB::table('users')->where('email',$email)->first();abort_if($u&&($u->is_support_staff||$u->is_support_coordinator)&&$u->internal_active,409,'Cette personne est déjà membre de l’équipe interne.');$data=['invited_by'=>$r->user()->id,'token_hash'=>hash('sha256',$token),'staff'=>$d['staff'],'coordinator'=>$d['coordinator'],'expires_at'=>now()->addDays(config('socle.invitation_days',7)),'accepted_at'=>null,'updated_at'=>now()];if($old){DB::table('organization_invitations')->where('id',$old->id)->update($data);$id=$old->id;}else $id=DB::table('organization_invitations')->insertGetId($data+['email'=>$email,'created_at'=>now()]);DB::table('tenant_audit_logs')->insert(['user_id'=>$r->user()->id,'action'=>'internal.invitation.created','payload'=>json_encode(['invitation_id'=>$id]),'created_at'=>now(),'updated_at'=>now()]);Outbox::push($r->user()->id,'internal-invite:'.hash('sha256',$token),'Invitation à l’équipe d’accompagnement',rtrim(config('socle.frontend_url'),'/').'/internal-invitation#token='.$token,null,$email);});return response()->json(['message'=>'Invitation préparée. Aucun rôle accordé avant acceptation.'],201);}
 public function update(Request $r,string $id){$this->admin($r);$d=$r->validate(['internal_active'=>['required','boolean'],'version'=>['required','integer','min:1'],'reason'=>['required','string','max:2000','regex:/\S/u']]);DB::transaction(function()use($r,$id,$d){$u=User::lockForUpdate()->findOrFail($id);abort_unless($u->is_support_staff||$u->is_support_coordinator,404);abort_unless($u->internal_version===(int)$d['version'],409,'Version périmée.');$u->forceFill(['internal_active'=>$d['internal_active'],'internal_version'=>$u->internal_version+1])->save();DB::table('tenant_audit_logs')->insert(['user_id'=>$r->user()->id,'action'=>'internal.member.state','payload'=>json_encode(['target'=>$u->id,'active'=>$d['internal_active'],'reason'=>$d['reason']]),'created_at'=>now(),'updated_at'=>now()]);Outbox::push($u->id,'internal-state:'.$u->id.':'.$u->internal_version,'Accès entreprise modifié','Votre accès d’accompagnement a changé. Votre compte personnel et vos autres appartenances sont conservés.');});return response()->json(['message'=>'État interne enregistré.']);}
 public function accept(Request $r){$d=$r->validate(['token'=>['required','string','size:64'],'email'=>['required','email'],'name'=>['nullable','string','max:120'],'password'=>['nullable','confirmed',Password::min(12)->letters()->numbers(),'max:128']]);$authenticated=Auth::guard('sanctum')->user();return DB::transaction(function()use($r,$d,$authenticated){$invite=DB::table('organization_invitations')->where('token_hash',hash('sha256',$d['token']))->lockForUpdate()->first();abort_unless($invite&&!$invite->accepted_at&&now()->lt($invite->expires_at)&&hash_equals($invite->email,strtolower(trim($d['email']))),422,'Invitation invalide ou indisponible.');$u=User::where('email',$invite->email)->lockForUpdate()->first();if($u){abort_unless($authenticated&&$authenticated->id===$u->id,422,'Connectez-vous au compte destinataire avant d’accepter.');}else{abort_if($authenticated,422,'Déconnectez-vous avant de créer ce compte.');$r->validate(['name'=>['required','string','max:120','regex:/\S/u'],'password'=>['required','confirmed',Password::min(12)->letters()->numbers(),'max:128']]);$u=User::create(['email'=>$invite->email,'name'=>$d['name'],'password'=>$d['password']]);}$u->forceFill(['is_support_staff'=>(bool)$invite->staff||$u->is_support_staff,'is_support_coordinator'=>(bool)$invite->coordinator||$u->is_support_coordinator,'internal_active'=>true,'internal_version'=>$u->internal_version+1,'email_verified_at'=>$u->email_verified_at??now()])->save();DB::table('organization_invitations')->where('id',$invite->id)->update(['accepted_at'=>now(),'updated_at'=>now()]);DB::table('tenant_audit_logs')->insert(['user_id'=>$u->id,'action'=>'internal.invitation.accepted','payload'=>json_encode(['invitation_id'=>$invite->id,'target'=>$u->id]),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['token'=>Security::token($u)],201)->header('Cache-Control','no-store');});}
}
